```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ifstream plik("uczniowie.txt");
    string imie;
    int wynik;
    vector<pair<int, string>> dane;
    while (plik >> imie >> wynik) {
        dane.push_back({wynik, imie});
    }
    sort(dane.begin(), dane.end(), [](auto& a, auto& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second < b.second;
    });
    cout << "Ranking uczniow:" << endl;
    for (int i = 0; i < (int)dane.size(); i++) {
        if (i + 1 < 10) cout << " ";
        cout << i + 1 << ". " << dane[i].second << ": " << dane[i].first << endl;
    }
    cout << "Najlepsza osoba: " << dane[0].second << " (" << dane[0].first << ")" << endl;
    return 0;
}
```

